-- VOLTÉO cloud. No direct client grants on business tables.
-- Private transactional API: explicit ownership checks, current DB roles and live Auth sessions.
create schema if not exists volteo_private;
revoke all on schema volteo_private from public;
create table volteo_private.dealers(id bigint generated by default as identity primary key, data jsonb not null);
create table volteo_private.vehicles(slug text primary key, data jsonb not null);
create table volteo_private.articles(slug text primary key, data jsonb not null);
create table volteo_private.users(
 id uuid primary key references auth.users(id) on delete cascade,
 email text not null, name text not null, role text not null default 'user' check(role in ('user','dealer','admin')),
 dealer_id bigint references volteo_private.dealers(id), account_type text not null default 'buyer' check(account_type in ('buyer','pro')),
 phone text not null default '', postcode text not null default '', company text not null default '', registration_id text not null default '',
 created double precision not null default extract(epoch from now()),
 check(role <> 'dealer' or dealer_id is not null)
);
create index users_dealer on volteo_private.users(dealer_id);
create table volteo_private.profiles(user_id uuid primary key references volteo_private.users(id) on delete cascade,data jsonb not null);
create table volteo_private.buyer_projects(user_id uuid primary key references volteo_private.users(id) on delete cascade,data jsonb not null,updated double precision not null);
create table volteo_private.favorites(user_id uuid references volteo_private.users(id) on delete cascade,vehicle_slug text references volteo_private.vehicles(slug),primary key(user_id,vehicle_slug));
create index favorites_vehicle on volteo_private.favorites(vehicle_slug);
create table volteo_private.simulations(id text primary key,user_id uuid not null references volteo_private.users(id) on delete cascade,data jsonb not null,created double precision not null);
create index simulations_owner on volteo_private.simulations(user_id,created desc);
create table volteo_private.leads(id text primary key,user_id uuid not null references volteo_private.users(id) on delete cascade,vehicle_slug text not null references volteo_private.vehicles(slug),dealer_id bigint not null references volteo_private.dealers(id),message text not null,phone text not null,status text not null default 'Nouveau' check(status in ('Nouveau','Contacté','Essai planifié','Terminé','Fermé')),created double precision not null,updated double precision not null);
create index leads_owner on volteo_private.leads(user_id,created desc);
create index leads_dealer on volteo_private.leads(dealer_id,created desc);
create index leads_vehicle on volteo_private.leads(vehicle_slug);
create table volteo_private.lead_details(lead_id text primary key references volteo_private.leads(id) on delete cascade,project jsonb,consent_version text not null,consent_at double precision not null,appointment double precision,reply text not null default '',trial jsonb not null default '{}',feedback jsonb not null default '{}',attendance_code text not null,attended_at double precision);
create table volteo_private.lead_events(id bigint generated always as identity primary key,lead_id text not null references volteo_private.leads(id) on delete cascade,actor uuid references volteo_private.users(id) on delete set null,status text not null,created double precision not null,detail text not null default '');
create index events_lead on volteo_private.lead_events(lead_id,id);
create index events_actor on volteo_private.lead_events(actor);
create table volteo_private.pilot_settings(id integer primary key check(id=1),radius integer not null check(radius in (10,15,20,25,30,50)),updated double precision not null);
create table volteo_private.pilot_partners(dealer_id bigint primary key references volteo_private.dealers(id),data jsonb not null,updated double precision not null);
create table volteo_private.pilot_offers(id text primary key,dealer_id bigint not null references volteo_private.dealers(id),vehicle_slug text not null references volteo_private.vehicles(slug),data jsonb not null,updated double precision not null);
create index offers_dealer on volteo_private.pilot_offers(dealer_id,updated desc);
create index offers_vehicle on volteo_private.pilot_offers(vehicle_slug);
create table volteo_private.pilot_enrollments(user_id uuid primary key references volteo_private.users(id) on delete cascade,data jsonb not null,created double precision not null,updated double precision not null);
-- Commune reference cache populated only by the geo Edge Function from geo.api.gouv.fr.
create table volteo_private.communes(postcode text not null,code text not null,data jsonb not null,updated timestamptz not null default now(),primary key(postcode,code));
create table volteo_private.attempts(key text primary key,count integer not null,expires timestamptz not null);
create index attempts_expiry on volteo_private.attempts(expires);

create function volteo_private.fail(message text,code text default 'PT400') returns void language plpgsql set search_path='' as $$begin raise exception using errcode=code,message=message;end$$;
create function volteo_private.txt(d jsonb,k text,lo integer default 0,hi integer default 1000) returns text language plpgsql immutable set search_path='' as $$declare v text;begin
 if d ? k and jsonb_typeof(d->k)<>'string' then perform volteo_private.fail('Champ invalide : '||k);end if;
 v=btrim(coalesce(d->>k,''));if length(v)<lo or length(v)>hi then perform volteo_private.fail('Champ invalide : '||k);end if;return v;end$$;
create function volteo_private.num(d jsonb,k text,lo numeric,hi numeric,def numeric) returns numeric language plpgsql immutable set search_path='' as $$declare v numeric;begin
 if not d ? k then return def;end if;
 if jsonb_typeof(d->k)<>'number' then perform volteo_private.fail('Valeur invalide : '||k);end if;
 v=(d->>k)::numeric;if v<lo or v>hi then perform volteo_private.fail('Valeur invalide : '||k);end if;return v;end$$;
create function volteo_private.choice(d jsonb,k text,options text[],def text default null) returns text language plpgsql immutable set search_path='' as $$declare v text:=coalesce(d->>k,def);begin if v is null or not(v=any(options)) then perform volteo_private.fail('Choix invalide : '||k);end if;return v;end$$;
create function volteo_private.priorities(d jsonb,k text) returns jsonb language plpgsql immutable set search_path='' as $$declare v jsonb:=coalesce(d->k,'[]');begin
 if jsonb_typeof(v)<>'array' then perform volteo_private.fail('Priorités invalides');end if;
 if jsonb_array_length(v)>7 or exists(select 1 from jsonb_array_elements_text(v) t(x) where x not in ('Autoroute','Stationnement','Coffre','Sièges enfants','Accessibilité','Recharge','Confort')) then perform volteo_private.fail('Priorités invalides');end if;return v;end$$;
create function volteo_private.distance(lat double precision,lon double precision) returns double precision language sql immutable set search_path='' as $$select round((6371*2*asin(least(1,sqrt(power(sin(radians(lat-48.6817)/2),2)+cos(radians(48.6817))*cos(radians(lat))*power(sin(radians(lon-2.1864)/2),2)))))::numeric,2)::double precision$$;
create function volteo_private.config() returns jsonb language sql stable set search_path='' as $$select '{"name":"Pilote Les Ulis","city":"Les Ulis","postcode":"91940","code":"91692","lat":48.6817,"lon":2.1864,"radii":[10,15,20,25,30,50],"source":"https://geo.api.gouv.fr/communes/91692?fields=nom,code,centre","centerChecked":"2026-10-04"}'::jsonb||jsonb_build_object('radius',coalesce((select radius from volteo_private.pilot_settings where id=1),20))$$;
create function volteo_private.active_partner(did bigint) returns boolean language sql stable set search_path='' as $$select coalesce((select data->>'status'='verified' and volteo_private.distance((data->>'lat')::float8,(data->>'lon')::float8)<=(volteo_private.config()->>'radius')::int from volteo_private.pilot_partners where dealer_id=did),false)$$;
create function volteo_private.offer(oid text,include_private boolean default false) returns jsonb language plpgsql stable set search_path='' as $$declare o volteo_private.pilot_offers;p jsonb;fresh boolean;visible boolean;begin
 select * into o from volteo_private.pilot_offers where id=oid;if not found then return null;end if;
 select data into p from volteo_private.pilot_partners where dealer_id=o.dealer_id;
 fresh=(o.data->>'valid_until')::float8>extract(epoch from now()) and o.updated>=extract(epoch from now())-604800;
 visible=o.data->>'status'='published' and fresh and volteo_private.active_partner(o.dealer_id);
 if not include_private and not visible then return null;end if;
 return o.data||jsonb_build_object('id',o.id,'dealer_id',o.dealer_id,'vehicle_slug',o.vehicle_slug,'updated',o.updated,'fresh',fresh,'visible',visible,'partner',case when p is null then null else p-'evidence'-'status'-'brands' end,'pilot_distance',volteo_private.distance((p->>'lat')::float8,(p->>'lon')::float8));end$$;
create function volteo_private.leads_view(u volteo_private.users) returns jsonb language sql stable set search_path='' as $$
 select coalesce(jsonb_agg(item order by created desc),'[]') from (
 select l.created,to_jsonb(l)||jsonb_build_object('name',b.name,'email',b.email,'project',d.project,'consent_version',d.consent_version,'consent_at',d.consent_at,'appointment',d.appointment,'reply',d.reply,'trial',d.trial,'attended_at',d.attended_at,'feedback',case when l.user_id=u.id or d.feedback->'shared'='true' then d.feedback else '{}'::jsonb end)||case when l.user_id=u.id and extract(epoch from now()) between d.appointment-7200 and d.appointment+172800 then jsonb_build_object('attendance_code',d.attendance_code) else '{}'::jsonb end item
 from volteo_private.leads l join volteo_private.users b on b.id=l.user_id join volteo_private.lead_details d on d.lead_id=l.id
 where u.role='admin' or (u.role='dealer' and l.dealer_id=u.dealer_id) or (u.role='user' and l.user_id=u.id)) q$$;
create function volteo_private.project(d jsonb,full_project boolean default true) returns jsonb language plpgsql set search_path='' as $$declare r jsonb:='{}';k text;v text;b jsonb;begin
 for k,b in select * from jsonb_each('{"budget":[1000,500000,40000],"km":[0,200000,15000],"daily":[0,1000,40],"seats":[1,9,5]}'::jsonb) loop r=r||jsonb_build_object(k,volteo_private.num(d,k,(b->>0)::numeric,(b->>1)::numeric,(b->>2)::numeric));end loop;
 r=r||jsonb_build_object('charging',volteo_private.choice(d,'charging',array['home','work','public']),'usage',volteo_private.choice(d,'usage',array['city','mixed','highway']),'category',volteo_private.choice(d,'category',array['Toutes','Citadine','Compacte','Berline','SUV','Familiale','Premium']));
 if not full_project then return r;end if;
 for k,b in select * from jsonb_each('{"radius":[5,200,50],"monthly":[0,10000,0],"longTrip":[0,3000,300],"winterMargin":[20,50,30],"chargeRate":[0,10,0.25],"chargePower":[0.5,350,7.4],"chargeSessions":[1,14,2],"detourMinutes":[0,240,0]}'::jsonb) loop r=r||jsonb_build_object(k,volteo_private.num(d,k,(b->>0)::numeric,(b->>1)::numeric,(b->>2)::numeric));end loop;
 r=r||jsonb_build_object('horizon',volteo_private.choice(d,'horizon',array['exploring','3months','6months','year']),'payment',volteo_private.choice(d,'payment',array['undecided','cash','finance']),'tradeIn',volteo_private.choice(d,'tradeIn',array['undecided','yes','no']),'parking',volteo_private.choice(d,'parking',array['unknown','private','shared','street'],'unknown'),'chargingReady',volteo_private.choice(d,'chargingReady',array['unknown','confirmed','unavailable'],'unknown'),'notes',volteo_private.txt(d,'notes',0,1000),'trialPriorities',volteo_private.priorities(d,'trialPriorities'));
 v=volteo_private.txt(d,'postcode',5,5);if v !~ '^\d{5}$' then perform volteo_private.fail('Code postal invalide');end if;r=r||jsonb_build_object('postcode',v);
 foreach k in array array['primaryStation','backupStation','primarySource','backupSource','chargingNotes'] loop v=volteo_private.txt(d,k,0,500);if k in ('primarySource','backupSource') and v<>'' and v !~ '^https?://' then perform volteo_private.fail('Lien de source invalide');end if;r=r||jsonb_build_object(k,v);end loop;
 v=volteo_private.txt(d,'chargeChecked',0,10);if v<>'' and (v !~ '^\d{4}-\d{2}-\d{2}$' or v::date>current_date) then perform volteo_private.fail('Date de vérification invalide');end if;return r||jsonb_build_object('chargeChecked',v);end$$;

-- Metadata supplies only contact details. Role/dealer binding are never copied from a JWT or metadata.
create function volteo_private.on_signup() returns trigger language plpgsql security definer set search_path='' as $$declare d jsonb:=new.raw_user_meta_data;k text;kind text;begin
 kind=volteo_private.choice(d,'account_type',array['buyer','pro'],'buyer');
 if coalesce(d->>'app','')='volteo' then
  perform volteo_private.txt(d,'name',2,80);
  if coalesce(d->>'postcode','') !~ '^\d{5}$' or d->'privacy_ack' is distinct from 'true'::jsonb then perform volteo_private.fail('Code postal et lecture de la notice requis');end if;
  if coalesce(d->>'phone','')<>'' and d->>'phone' !~ '^[+0-9 ().-]{8,25}$' then perform volteo_private.fail('Téléphone invalide');end if;
  if kind='pro' then perform volteo_private.txt(d,'company',2,120);if coalesce(d->>'registration_id','') !~ '^(\d{9}|\d{14})$' or coalesce(d->>'phone','')='' then perform volteo_private.fail('Coordonnées professionnelles incomplètes');end if;end if;
 end if;
 insert into volteo_private.users(id,email,name,account_type,phone,postcode,company,registration_id) values(new.id,coalesce(new.email,''),left(coalesce(nullif(d->>'name',''),'Utilisateur'),80),kind,left(coalesce(d->>'phone',''),25),left(coalesce(d->>'postcode',''),5),case when kind='pro' then left(coalesce(d->>'company',''),120) else '' end,case when kind='pro' then left(coalesce(d->>'registration_id',''),14) else '' end);return new;end$$;
create trigger volteo_signup after insert on auth.users for each row execute function volteo_private.on_signup();

create function volteo_private.dispatch(p text,m text,d jsonb,u volteo_private.users) returns jsonb language plpgsql set search_path='' as $$
declare r jsonb;v jsonb;b jsonb;clean jsonb;old jsonb;tr jsonb;cfg jsonb;item jsonb;items jsonb;statuses jsonb;reasons jsonb;
 uid uuid:=u.id;stamp float8:=extract(epoch from clock_timestamp());did bigint;lid text;slug text;k text;s text;oid text;apt float8;prev float8;changed integer;dist float8;days numeric;
 l volteo_private.leads;detail volteo_private.lead_details;o volteo_private.pilot_offers;pa volteo_private.pilot_partners;
begin
 if m='GET' then
  if p='/vehicles' then return (select coalesce(jsonb_agg(data order by slug),'[]') from volteo_private.vehicles);end if;
  if p='/dealers' then return (select coalesce(jsonb_agg(data order by id),'[]') from volteo_private.dealers);end if;
  if p='/articles' then return (select coalesce(jsonb_agg(data order by slug),'[]') from volteo_private.articles);end if;
  if p='/pilot' then return volteo_private.config();end if;
  if p='/pilot/offers' then return (select coalesce(jsonb_agg(x order by updated desc),'[]') from (select volteo_private.offer(id) x,updated from volteo_private.pilot_offers) q where x is not null);end if;
  if p='/session' then return jsonb_build_object('user',case when uid is null then null else to_jsonb(u)-'created' end,'csrf',null);end if;
 end if;
 if uid is null then perform volteo_private.fail('Connectez-vous pour continuer','PT401');end if;
 if m in ('POST','PUT') and p in ('/profile','/project','/leads','/pilot/enrollment') and (u.account_type='pro' or u.role<>'user') then perform volteo_private.fail('Cette action appartient au parcours acheteur','PT403');end if;
 if p='/me' and m='GET' then return jsonb_build_object('project',(select data from volteo_private.buyer_projects where user_id=uid),'profile',(select data from volteo_private.profiles where user_id=uid),'favorites',(select coalesce(jsonb_agg(vehicle_slug),'[]') from volteo_private.favorites where user_id=uid),'simulations',(select coalesce(jsonb_agg(to_jsonb(t) order by created desc),'[]') from volteo_private.simulations t where user_id=uid),'leads',volteo_private.leads_view(u));end if;
 if p='/project' then
  if m='GET' then select jsonb_build_object('project',data,'updated',updated) into r from volteo_private.buyer_projects where user_id=uid;return coalesce(r,'{"project":null,"updated":null}');end if;
  if m='DELETE' then delete from volteo_private.buyer_projects where user_id=uid;return '{"ok":true}';end if;
  if m='PUT' then
   clean=volteo_private.project(d);insert into volteo_private.buyer_projects values(uid,clean,stamp) on conflict(user_id) do update set data=excluded.data,updated=excluded.updated;
   insert into volteo_private.profiles values(uid,volteo_private.project(clean,false)) on conflict(user_id) do update set data=excluded.data;
   update volteo_private.users set postcode=clean->>'postcode' where id=uid;return jsonb_build_object('project',clean,'updated',stamp);
  end if;
 end if;
 if p='/profile' and m='PUT' then
  clean=volteo_private.project(d,false);insert into volteo_private.profiles values(uid,clean) on conflict(user_id) do update set data=excluded.data;
  update volteo_private.buyer_projects set data=data||clean,updated=stamp where user_id=uid;return clean;
 end if;
 if p like '/favorites/%' and m in ('PUT','DELETE') then
  slug=substr(p,12);if not exists(select 1 from volteo_private.vehicles where vehicles.slug=dispatch.slug) then perform volteo_private.fail('Véhicule introuvable','PT404');end if;
  if m='PUT' then insert into volteo_private.favorites values(uid,slug) on conflict do nothing;else delete from volteo_private.favorites where user_id=uid and vehicle_slug=slug;end if;return '{"ok":true}';
 end if;
 if p='/simulations' and m='POST' then
  clean='{}';for k,b in select * from jsonb_each('{"km":[0,200000,15000],"years":[1,15,5],"fuel":[0,10,1.85],"liters":[0,40,6],"homeRate":[0,10,0.25],"publicRate":[0,10,0.6],"homeShare":[0,100,80],"electricMaintenance":[0,10000,350],"thermalMaintenance":[0,10000,700],"electricInsurance":[0,10000,700],"thermalInsurance":[0,10000,650],"thermalValue":[0,500000,15000],"thermalResale":[0,500000,6000],"electricResale":[0,500000,18000],"deposit":[0,500000,5000],"months":[1,120,60],"apr":[0,30,4],"installation":[0,20000,1200]}'::jsonb) loop clean=clean||jsonb_build_object(k,volteo_private.num(d,k,(b->>0)::numeric,(b->>1)::numeric,(b->>2)::numeric));end loop;
  slug=volteo_private.txt(d,'vehicle',1,100);select data into v from volteo_private.vehicles where vehicles.slug=dispatch.slug;if v is null then perform volteo_private.fail('Véhicule invalide');end if;
  if (clean->>'deposit')::numeric>(v->>'priceMin')::numeric or (clean->>'electricResale')::numeric>(v->>'priceMin')::numeric or (clean->>'thermalResale')::numeric>(clean->>'thermalValue')::numeric then perform volteo_private.fail('Apport ou valeur de revente incohérente');end if;
  clean=clean||jsonb_build_object('vehicle',slug,'fuelSource',volteo_private.txt(d,'fuelSource',0,500));oid=replace(gen_random_uuid()::text,'-','');insert into volteo_private.simulations values(oid,uid,clean,stamp);return jsonb_build_object('id',oid);
 end if;
 if p='/leads' and m='GET' then return volteo_private.leads_view(u);end if;
 if p='/leads' and m='POST' then
  slug=volteo_private.txt(d,'vehicle',1,100);did=volteo_private.num(d,'dealer_id',1,2147483647,0);if d->>'dealer_id' !~ '^\d+$' then perform volteo_private.fail('Concession invalide');end if;
  select data into v from volteo_private.vehicles where vehicles.slug=dispatch.slug;select data into b from volteo_private.dealers where id=did;
  if v is null or b is null or b->'essai' is distinct from 'true'::jsonb or not(b->'brands' ? (v->>'brand')) then perform volteo_private.fail('Cette concession ne propose pas ce véhicule en essai');end if;
  if d->'consent' is distinct from 'true'::jsonb then perform volteo_private.fail('Autorisez la transmission à la concession choisie');end if;
  s=volteo_private.txt(d,'phone',8,25);if s !~ '^[+0-9 ().-]{8,25}$' then perform volteo_private.fail('Téléphone invalide');end if;
  tr=coalesce(d->'trial','{}');if jsonb_typeof(tr)<>'object' then perform volteo_private.fail('Préparation d’essai invalide');end if;
  tr=jsonb_build_object('priorities',volteo_private.priorities(tr,'priorities'),'route',volteo_private.txt(tr,'route',0,600),'mode','demo');
  oid=volteo_private.txt(d,'offer_id',0,60);
  if oid<>'' then
   item=volteo_private.offer(oid);if item is null or (item->>'dealer_id')::bigint<>did or item->>'vehicle_slug'<>slug then perform volteo_private.fail('Cette offre n’est plus disponible. Actualisez les offres locales.','PT409');end if;
   tr=tr||jsonb_build_object('mode','partner','offer',(select jsonb_object_agg(key,value) from jsonb_each(item) where key=any(array['id','trim','cash_price','fees','availability','valid_until','updated','terms'])));
  elsif b->'pilot'='true' then perform volteo_private.fail('Choisissez une offre locale active de ce partenaire');end if;
  clean=null;if d->'share_project'='true' then select data into clean from volteo_private.buyer_projects where user_id=uid;if clean is null then perform volteo_private.fail('Enregistrez votre dossier avant de le partager');end if;end if;
  lid=replace(gen_random_uuid()::text,'-','');insert into volteo_private.leads values(lid,uid,slug,did,volteo_private.txt(d,'message',0,2000),s,'Nouveau',stamp,stamp);
  insert into volteo_private.lead_details(lead_id,project,consent_version,consent_at,trial,attendance_code) values(lid,clean,case when clean is null then 'trial-v2-contact' else 'trial-v2-project' end,stamp,tr,lpad(((('x'||substr(replace(gen_random_uuid()::text,'-',''),1,8))::bit(32)::bigint)%1000000)::text,6));
  insert into volteo_private.lead_events(lead_id,actor,status,created) values(lid,uid,'Nouveau',stamp);return jsonb_build_object('id',lid);
 end if;
 if p ~ '^/leads/[a-f0-9]+$' and m in ('GET','PATCH','DELETE') then
  lid=split_part(p,'/',3);select * into l from volteo_private.leads where id=lid for update;
  if not found then perform volteo_private.fail('Demande introuvable','PT404');end if;
  if not(u.role='admin' or u.role='dealer' and u.dealer_id=l.dealer_id or m in ('GET','DELETE') and l.user_id=uid) then perform volteo_private.fail('Accès réservé','PT403');end if;
  if m='GET' then return(select coalesce(jsonb_agg(jsonb_build_object('status',status,'created',created,'detail',lead_events.detail) order by id),'[]') from volteo_private.lead_events where lead_id=lid);end if;
  if m='DELETE' then delete from volteo_private.leads where id=lid;return '{"ok":true}';end if;
  if (d->>'expected_updated')::float8 is distinct from l.updated then perform volteo_private.fail('Cette demande a été modifiée. Rechargez la liste.','PT409');end if;
  s=volteo_private.choice(d,'status',array['Nouveau','Contacté','Essai planifié','Terminé','Fermé']);select * into detail from volteo_private.lead_details where lead_id=lid;
  apt=detail.appointment;if s='Essai planifié' then apt=volteo_private.num(d,'appointment',stamp+1,stamp+366*86400,0);if apt=0 then perform volteo_private.fail('Choisissez un créneau futur');end if;end if;
  if detail.attended_at is not null and (s<>'Terminé' or apt is distinct from detail.appointment) then perform volteo_private.fail('Un essai confirmé ne peut plus être replanifié ou fermé');end if;
  update volteo_private.leads set status=s,updated=stamp where id=lid;
  update volteo_private.lead_details set appointment=apt,reply=volteo_private.txt(d,'reply',0,1000),attendance_code=case when apt is distinct from detail.appointment then lpad(((('x'||substr(replace(gen_random_uuid()::text,'-',''),1,8))::bit(32)::bigint)%1000000)::text,6) else attendance_code end where lead_id=lid;
  insert into volteo_private.lead_events(lead_id,actor,status,created,detail) values(lid,uid,s,stamp,jsonb_build_object('appointment',apt,'reply',volteo_private.txt(d,'reply',0,1000))::text);return '{"ok":true}';
 end if;
 if p='/export' and m='GET' then
  return jsonb_build_object('user',to_jsonb(u)-'created','profile',(select coalesce(jsonb_agg(data),'[]') from volteo_private.profiles where user_id=uid),'project',(select coalesce(jsonb_agg(jsonb_build_object('data',data,'updated',updated)),'[]') from volteo_private.buyer_projects where user_id=uid),'favorites',(select coalesce(jsonb_agg(vehicle_slug),'[]') from volteo_private.favorites where user_id=uid),'simulations',(select coalesce(jsonb_agg(to_jsonb(t)),'[]') from volteo_private.simulations t where user_id=uid),'leads',(select coalesce(jsonb_agg(to_jsonb(t)),'[]') from volteo_private.leads t where user_id=uid),'lead_details',(select coalesce(jsonb_agg(to_jsonb(t)-'attendance_code'),'[]') from volteo_private.lead_details t join volteo_private.leads l on l.id=t.lead_id where l.user_id=uid),'pilot_enrollment',(select coalesce(jsonb_agg(data),'[]') from volteo_private.pilot_enrollments where user_id=uid));
 end if;
 if p='/admin/users' and m='GET' then
  if u.role<>'admin' then perform volteo_private.fail('Accès réservé','PT403');end if;return(select coalesce(jsonb_agg(to_jsonb(t)-'created'),'[]') from volteo_private.users t);
 end if;
 if p like '/admin/users/%' and m='PATCH' then
  if u.role<>'admin' then perform volteo_private.fail('Accès réservé','PT403');end if;
  k=split_part(p,'/',4);if k=uid::text then perform volteo_private.fail('Votre propre rôle ne peut pas être modifié ici');end if;
  s=volteo_private.choice(d,'role',array['user','dealer','admin']);did=null;
  if s='dealer' then did=volteo_private.num(d,'dealer_id',1,2147483647,0);if not exists(select 1 from volteo_private.dealers where id=did) then perform volteo_private.fail('Concession requise');end if;end if;
  update volteo_private.users set role=s,dealer_id=did where id=k::uuid;if not found then perform volteo_private.fail('Compte introuvable','PT404');end if;
  -- Every request reads the current database role; no stale role claims.
  return '{"ok":true}';
 end if;
 if p like '/admin/vehicles/%' and m='PUT' then
  if u.role<>'admin' then perform volteo_private.fail('Accès réservé','PT403');end if;slug=split_part(p,'/',4);select data into v from volteo_private.vehicles where vehicles.slug=dispatch.slug;
  if v is null then perform volteo_private.fail('Véhicule introuvable','PT404');end if;
  for k,b in select * from jsonb_each('{"priceMin":[0,1000000,0],"priceMax":[0,1000000,0],"autonomy":[1,2000,1],"conso":[1,100,1],"fastKW":[0,1000,0]}'::jsonb) loop v=v||jsonb_build_object(k,volteo_private.num(d,k,(b->>0)::numeric,(b->>1)::numeric,(b->>2)::numeric));end loop;
  if (v->>'priceMax')::numeric<(v->>'priceMin')::numeric then perform volteo_private.fail('Fourchette de prix invalide');end if;
  v=v||jsonb_build_object('source',volteo_private.txt(d,'source',0,500),'updatedAt',current_date::text,'dataStatus','Démonstration — non vérifié');update volteo_private.vehicles set data=v where vehicles.slug=dispatch.slug;return v;
 end if;
 if p='/pilot/settings' and m='PUT' then
  if u.role<>'admin' then perform volteo_private.fail('Accès réservé','PT403');end if;
  if coalesce(d->>'radius','') not in ('10','15','20','25','30','50') then perform volteo_private.fail('Rayon invalide');end if;
  insert into volteo_private.pilot_settings values(1,(d->>'radius')::int,stamp) on conflict(id) do update set radius=excluded.radius,updated=excluded.updated;return volteo_private.config();
 end if;
 if p='/pilot/enrollment' then
  if u.account_type='pro' or u.role<>'user' then perform volteo_private.fail('Inscription réservée aux acheteurs','PT403');end if;
  if m='GET' then return(select data||jsonb_build_object('updated',updated) from volteo_private.pilot_enrollments where user_id=uid);end if;
  if m='DELETE' then delete from volteo_private.pilot_enrollments where user_id=uid;return '{"ok":true}';end if;
  if m='PUT' then
   if d->'consent' is distinct from 'true'::jsonb then perform volteo_private.fail('Confirmez votre participation au pilote');end if;
   select data into v from volteo_private.communes where postcode=volteo_private.txt(d,'postcode',5,5) and code=volteo_private.txt(d,'city_code',5,5) and updated>now()-interval '7 days';
   if v is null then perform volteo_private.fail('Vérifiez votre commune avant de participer');end if;
   cfg=volteo_private.config();dist=volteo_private.distance((v->>'lat')::float8,(v->>'lon')::float8);
   clean=jsonb_build_object('city',v->>'name','city_code',d->>'city_code','postcode',d->>'postcode','distance',dist,'status',case when dist<=(cfg->>'radius')::int then 'pilot' else 'outside' end,'source',volteo_private.choice(d,'source',array['meta','google','friend','dealer','other'],'other'),'consent_at',stamp,'consent_version','pilot-interest-v1','radius_at_signup',cfg->'radius');
   insert into volteo_private.pilot_enrollments values(uid,clean,stamp,stamp) on conflict(user_id) do update set data=excluded.data,updated=excluded.updated;return clean;
  end if;
 end if;
 if p='/pilot/partners' and m in ('GET','PUT') then
  if u.role<>'admin' then perform volteo_private.fail('Accès réservé','PT403');end if;
  if m='GET' then return(select coalesce(jsonb_agg(data||jsonb_build_object('dealer_id',dealer_id,'updated',updated)),'[]') from volteo_private.pilot_partners);end if;
  did=(d->>'dealer_id')::bigint;if did is not null then select * into pa from volteo_private.pilot_partners where dealer_id=did for update;if pa.dealer_id is not null and (d->>'expected_updated')::float8 is distinct from pa.updated then perform volteo_private.fail('Établissement modifié. Rechargez.','PT409');end if;end if;
  s=volteo_private.choice(d,'status',array['pending','verified','suspended']);if s='verified' and d->'verification_ack' is distinct from 'true'::jsonb then perform volteo_private.fail('Confirmez la vérification du partenariat');end if;
  clean=jsonb_build_object('name',volteo_private.txt(d,'name',2,120),'city',volteo_private.txt(d,'city',2,120),'address',volteo_private.txt(d,'address',5,300),'evidence',volteo_private.txt(d,'evidence',10,1000),'lat',volteo_private.num(d,'lat',-90,90,48.6817),'lon',volteo_private.num(d,'lon',-180,180,2.1864),'status',s,'verified_at',case when s='verified' then stamp else null end);
  b=coalesce(d->'brands','[]');if jsonb_typeof(b)<>'array' then perform volteo_private.fail('Marques invalides');end if;
  if jsonb_array_length(b)=0 or exists(select 1 from jsonb_array_elements_text(b) t(x) where not exists(select 1 from volteo_private.vehicles where data->>'brand'=x)) then perform volteo_private.fail('Choisissez les marques représentées');end if;clean=clean||jsonb_build_object('brands',b);
  if did is null then insert into volteo_private.dealers(data) values('{}') returning id into did;elsif not exists(select 1 from volteo_private.dealers where id=did) then perform volteo_private.fail('Établissement introuvable');end if;
  v=clean-'evidence'-'status'-'verified_at'||jsonb_build_object('id',did,'essai',s='verified','partenaire',s='verified','pilot',true,'dataStatus',case when s='verified' then 'Partenaire validé manuellement' else 'Partenaire non actif' end);
  update volteo_private.dealers set data=v where id=did;
  insert into volteo_private.pilot_partners values(did,clean,stamp) on conflict(dealer_id) do update set data=excluded.data,updated=excluded.updated;return clean||jsonb_build_object('dealer_id',did,'updated',stamp);
 end if;
 if p='/pilot/inventory' or p like '/pilot/inventory/%' then
  if u.role not in ('dealer','admin') then perform volteo_private.fail('Accès réservé','PT403');end if;
  if p='/pilot/inventory' and m='GET' then return(select coalesce(jsonb_agg(volteo_private.offer(id,true) order by updated desc),'[]') from volteo_private.pilot_offers where u.role='admin' or dealer_id=u.dealer_id);end if;
  if m in ('POST','PUT') then
   if m='PUT' then oid=split_part(p,'/',4);select * into o from volteo_private.pilot_offers where id=oid for update;if not found then perform volteo_private.fail('Offre introuvable','PT404');end if;did=o.dealer_id;if (d->>'expected_updated')::float8 is distinct from o.updated then perform volteo_private.fail('Offre modifiée. Rechargez.','PT409');end if;
   else oid=replace(gen_random_uuid()::text,'-','');did=case when u.role='dealer' then u.dealer_id else (d->>'dealer_id')::bigint end;end if;
   if u.role='dealer' and did is distinct from u.dealer_id then perform volteo_private.fail('Accès réservé','PT403');end if;
   if not volteo_private.active_partner(did) then perform volteo_private.fail('Un partenaire validé dans le rayon du pilote est requis');end if;
   slug=volteo_private.txt(d,'vehicle_slug',1,100);select data into v from volteo_private.vehicles where vehicles.slug=dispatch.slug;select data into b from volteo_private.pilot_partners where dealer_id=did;
   if v is null or not(b->'brands' ? (v->>'brand')) then perform volteo_private.fail('Véhicule incompatible avec l’établissement');end if;
   if d->'stock_ack' is distinct from 'true'::jsonb then perform volteo_private.fail('Confirmez prix, frais et disponibilité');end if;
   days=volteo_private.num(d,'valid_days',1,7,7);clean=jsonb_build_object('trim',volteo_private.txt(d,'trim',3,200),'availability',volteo_private.txt(d,'availability',3,300),'terms',volteo_private.txt(d,'terms',3,1000),'source',volteo_private.txt(d,'source',5,500),'cash_price',volteo_private.num(d,'cash_price',1000,1000000,0),'fees',volteo_private.num(d,'fees',0,100000,0),'status',volteo_private.choice(d,'status',array['published','withdrawn'],'published'),'valid_until',stamp+days*86400);
   if (clean->>'cash_price')::numeric<1000 then perform volteo_private.fail('Prix requis');end if;
   insert into volteo_private.pilot_offers values(oid,did,slug,clean,stamp) on conflict(id) do update set vehicle_slug=excluded.vehicle_slug,data=excluded.data,updated=excluded.updated;return volteo_private.offer(oid,true);
  end if;
 end if;
 if p='/pilot/dashboard' and m='GET' then
  if u.role not in ('dealer','admin') then perform volteo_private.fail('Accès réservé','PT403');end if;
  items=volteo_private.leads_view(u);select coalesce(jsonb_agg(x),'[]') into r from jsonb_array_elements(items) x where x->'trial'->>'mode'='partner';
  statuses='{}';foreach s in array array['Nouveau','Contacté','Essai planifié','Terminé','Fermé'] loop statuses=statuses||jsonb_build_object(s,(select count(*) from jsonb_array_elements(r) x where x->>'status'=s));end loop;
  reasons='{}';foreach s in array array['budget','charging','range','comfort','availability','timing','other'] loop reasons=reasons||jsonb_build_object(s,(select count(*) from jsonb_array_elements(r) x where x->'feedback'->>'reason'=s));end loop;
  v=jsonb_build_object('demo_count',jsonb_array_length(items)-jsonb_array_length(r),'total',jsonb_array_length(r),'statuses',statuses,'reasons',reasons,'attended',(select count(*) from jsonb_array_elements(r) x where x->>'attended_at' is not null),'feedback',(select count(*) from jsonb_array_elements(r) x where x->'feedback'<>'{}'::jsonb),'purchases',(select count(*) from jsonb_array_elements(r) x where x->'feedback'->>'outcome'='purchased'));
  if u.role='admin' then clean='{}';foreach s in array array['meta','google','friend','dealer','other'] loop clean=clean||jsonb_build_object(s,(select count(*) from volteo_private.pilot_enrollments where data->>'source'=s));end loop;
   v=v||jsonb_build_object('enrollments',jsonb_build_object('total',(select count(*) from volteo_private.pilot_enrollments),'inside',(select count(*) from volteo_private.pilot_enrollments where (data->>'distance')::float8<=(volteo_private.config()->>'radius')::int),'sources',clean));end if;return v;
 end if;
 if p ~ '^/pilot/leads/[a-f0-9]+/(feedback|attendance)$' then
  lid=split_part(p,'/',4);k=split_part(p,'/',5);select * into l from volteo_private.leads where id=lid for update;if not found then perform volteo_private.fail('Demande introuvable','PT404');end if;select * into detail from volteo_private.lead_details where lead_id=lid;
  if k='feedback' and m='PUT' then
   if l.user_id<>uid then perform volteo_private.fail('Seul l’acheteur peut rédiger son bilan','PT403');end if;
   if detail.attended_at is null and (detail.appointment is null or detail.appointment>stamp) then perform volteo_private.fail('Le bilan sera disponible après le créneau');end if;
   clean=jsonb_build_object('outcome',volteo_private.choice(d,'outcome',array['pursue','compare','pause','purchased']),'reason',volteo_private.choice(d,'reason',array['none','budget','charging','range','comfort','availability','timing','other']),'liked',volteo_private.txt(d,'liked',0,1000),'next',volteo_private.txt(d,'next',0,1000),'shared',coalesce(d->'shared'='true',false),'updated',stamp);
   update volteo_private.lead_details set feedback=clean where lead_id=lid;return clean;
  end if;
  if k='attendance' and m='POST' then
   if u.role not in ('dealer','admin') or u.role='dealer' and u.dealer_id<>l.dealer_id then perform volteo_private.fail('Accès réservé','PT403');end if;
   if detail.appointment is null or stamp not between detail.appointment-7200 and detail.appointment+172800 then perform volteo_private.fail('Confirmation ouverte de 2 h avant à 48 h après le créneau');end if;
   if volteo_private.txt(d,'code',6,6)<>detail.attendance_code then perform volteo_private.fail('Code incorrect');end if;
   if detail.attended_at is not null then return '{"ok":true}';end if;
   update volteo_private.lead_details set attended_at=stamp where lead_id=lid;update volteo_private.leads set status='Terminé',updated=stamp where id=lid;
   insert into volteo_private.lead_events(lead_id,actor,status,created,detail) values(lid,uid,'Terminé',stamp,'{"attendance":"Code présenté par l’acheteur"}');return '{"ok":true}';
  end if;
 end if;
 perform volteo_private.fail('Route introuvable','PT404');return null;
end$$;

create function volteo_private.allow_attempt(k text,lim integer) returns boolean language plpgsql set search_path='' as $$declare n integer;begin
 delete from volteo_private.attempts where expires<now();
 insert into volteo_private.attempts values(k,1,now()+interval '15 minutes') on conflict(key) do update set count=attempts.count+1 returning count into n;return n<=lim;end$$;
create function volteo_private.request(path text,method text,payload jsonb default '{}') returns jsonb language plpgsql security definer set search_path='' as $$
declare u volteo_private.users;uid uuid:=auth.uid();sid text:=auth.jwt()->>'session_id';result jsonb;state text;message text;begin
 if length(path)>200 or length(payload::text)>65536 or method not in ('GET','POST','PUT','PATCH','DELETE') or jsonb_typeof(payload)<>'object' then return '{"error":"Requête invalide","status":400}';end if;
 if uid is not null then
  if sid is null or not exists(select 1 from auth.sessions where id::text=sid and user_id=uid) then return '{"error":"Session expirée. Reconnectez-vous.","status":401}';end if;
  select * into u from volteo_private.users where id=uid;if not found then return '{"error":"Compte introuvable","status":401}';end if;
  if method<>'GET' and not volteo_private.allow_attempt('write:'||uid,100) then return '{"error":"Trop de tentatives. Réessayez dans 15 minutes.","status":429}';end if;
  if path='/leads' and method='POST' and not volteo_private.allow_attempt('lead:'||uid,10) then return '{"error":"Trop de demandes. Réessayez dans 15 minutes.","status":429}';end if;
  if path ~ '^/pilot/leads/[a-f0-9]+/attendance$' and not volteo_private.allow_attempt(uid||':'||path,5) then return '{"error":"Trop de codes essayés. Réessayez dans 15 minutes.","status":429}';end if;
 end if;
 -- Exception subtransaction rolls back domain writes, keeping failed-attempt counters above.
 begin return volteo_private.dispatch(path,method,payload,u);
 exception when others then get stacked diagnostics state=returned_sqlstate,message=message_text;
  if state like 'PT%' then return jsonb_build_object('error',message,'status',substr(state,3)::int);end if;
  if state like '22%' or state like '23%' then return '{"error":"Données invalides ou conflit. Vérifiez les champs.","status":400}';end if;
  raise warning 'VOLTEO dispatch failed SQLSTATE %, route %',state,path;
  return '{"error":"Erreur du serveur. Réessayez.","status":500}';
 end;
end$$;
create function public.volteo_api(path text,method text default 'GET',payload jsonb default '{}') returns jsonb language sql security invoker set search_path='' as $$select volteo_private.request(path,method,payload)$$;

-- Service-only geographic cache/rate operations, called by the Edge Function.
create function public.volteo_geo_cache(postcode text,cities jsonb) returns void language plpgsql security invoker set search_path='' as $$begin
 if postcode !~ '^\d{5}$' or jsonb_typeof(cities)<>'array' then raise exception 'Invalid communes';end if;
 insert into volteo_private.communes(postcode,code,data) select postcode,x->>'code',x from jsonb_array_elements(cities) x on conflict(postcode,code) do update set data=excluded.data,updated=now();end$$;
create function public.volteo_geo_limit(bucket text) returns boolean language sql security invoker set search_path='' as $$select volteo_private.allow_attempt('geo:'||bucket,80)$$;

do $$declare t record;begin for t in select tablename from pg_tables where schemaname='volteo_private' loop execute format('alter table volteo_private.%I enable row level security',t.tablename);end loop;end$$;
revoke all on all tables in schema volteo_private from public,anon,authenticated;
revoke all on all functions in schema volteo_private from public,anon,authenticated;
revoke all on all sequences in schema volteo_private from public,anon,authenticated;
grant usage on schema volteo_private to anon,authenticated,service_role;
grant execute on function volteo_private.request(text,text,jsonb) to anon,authenticated,service_role;
grant execute on function public.volteo_api(text,text,jsonb) to anon,authenticated,service_role;
revoke all on function public.volteo_api(text,text,jsonb) from public;
revoke all on function public.volteo_geo_cache(text,jsonb),public.volteo_geo_limit(text) from public,anon,authenticated;
grant execute on function public.volteo_geo_cache(text,jsonb),public.volteo_geo_limit(text),volteo_private.allow_attempt(text,integer) to service_role;
grant select,insert,update,delete on volteo_private.communes,volteo_private.attempts to service_role;
alter default privileges in schema volteo_private revoke execute on functions from public;
notify pgrst,'reload schema';

